from soar.intel.mitre import parse_technique

import json

try:
    document = json.loads(payload)
except ValueError as error:
    return {"techniques": [], "spec_version": None,
            "errors": ["not valid JSON: %s" % error]}

if isinstance(document, dict):
    objects = document.get("objects")
    spec_version = document.get("spec_version")
else:
    objects = document
    spec_version = None
if not isinstance(objects, list):
    return {"techniques": [], "spec_version": None,
            "errors": ["no STIX object list in the document"]}

techniques = []
errors = []
seen = set()

for entry in objects:
    if not isinstance(entry, dict) or entry.get("type") != "attack-pattern":
        continue

    technique_id = None
    url = None
    for reference in entry.get("external_references") or []:
        if not isinstance(reference, dict):
            continue
        if str(reference.get("source_name", "")).startswith("mitre"):
            technique_id = reference.get("external_id")
            url = reference.get("url")
            break
    if not technique_id:
        if len(errors) < 20:
            errors.append("%s carries no MITRE external id" % entry.get("id"))
        continue

    parsed = parse_technique(technique_id)
    if not parsed["valid"]:
        if len(errors) < 20:
            errors.append("%s is not a technique id" % technique_id)
        continue
    if parsed["id"] in seen:
        continue

    tactics = []
    for phase in entry.get("kill_chain_phases") or []:
        if not isinstance(phase, dict):
            continue
        if not str(phase.get("kill_chain_name", "")).startswith("mitre"):
            continue
        name = str(phase.get("phase_name", "")).strip()
        if name and name not in tactics:
            tactics.append(name)
    if not tactics:
        if len(errors) < 20:
            errors.append("%s (%s) declares no tactic"
                          % (technique_id, entry.get("name")))
        continue

    seen.add(parsed["id"])
    techniques.append({
        "id": parsed["id"],
        "name": str(entry.get("name") or technique_id)[:300],
        "description": str(entry.get("description") or "")[:8000],
        "tactic": sorted(tactics)[0],
        "tactics": sorted(tactics),
        "platforms": [str(p) for p in (entry.get("x_mitre_platforms") or [])],
        "data_sources": [str(d) for d in (entry.get("x_mitre_data_sources") or [])],
        "detection": str(entry.get("x_mitre_detection") or "")[:8000],
        "revoked": bool(entry.get("revoked")
                        or entry.get("x_mitre_deprecated")),
        "version": str(entry.get("x_mitre_version") or "")[:16],
        "is_subtechnique": bool(entry.get("x_mitre_is_subtechnique")
                                or parsed["sub_technique"]),
        "parent_id": parsed["technique"] if parsed["sub_technique"] else None,
        "url": url,
        "last_modified": entry.get("modified"),
    })

return {"techniques": techniques, "spec_version": spec_version,
        "errors": errors}
